// ─────────────────────────────────────────────────────────────────────────────
// AP Chemistry — authored lesson content (detailed konspekt + homework), RU + EN.
//
// Keyed by lesson short_id (e.g. 'apchem-ru-0' / 'apchem-en-3'). Consumed by
// getLessonDetail() in lessonContent.ts: when an AP lesson is opened, its konspekt
// paragraphs and homework come from here instead of the generic generator.
//
// The course CATALOG (courses/modules/lessons rows) lives in Supabase so students
// can actually open these lessons; the written content lives here in code, exactly
// like every other course's konspekt in this app.
// ─────────────────────────────────────────────────────────────────────────────
import type { LessonParagraph, HomeworkQuizQuestion, HomeworkTeacherTask } from './lessonContent'

export interface ApLessonContent {
  paragraphs: LessonParagraph[]
  quiz: HomeworkQuizQuestion[]
  hardTask: HomeworkTeacherTask
}

const p = (id: string, text: string): LessonParagraph => ({ id, text })

// Small helper to keep quiz authoring compact.
const qq = (
  id: string, prompt: string, opts: string[], correctIdx: number, explanation: string,
): HomeworkQuizQuestion => ({
  id,
  prompt,
  options: opts.map((text, i) => ({ id: String.fromCharCode(97 + i), text })),
  correctOptionId: String.fromCharCode(97 + correctIdx),
  explanation,
})

